# Purpose: Log header file locations and GCC include search paths for OpenCV build diagnostics
# Parameters: None
# Returns: 0 on success, non-zero on failure
# Side effects: Creates diagnostic log files in /tmp
log_header_diagnostics() {
  local header_log="/tmp/opencv_header_locations.log"
  local gcc_include_log="/tmp/opencv_gcc_include_search.log"
  {
    printf 'Header diagnostics timestamp: %s\n' "$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
    printf 'Searching for stdlib.h / stdio.h under /usr/include (depth<=3)\n'
    find /usr/include -maxdepth 3 \( -name 'stdlib.h' -o -name 'stdio.h' \) -print 2>/dev/null || true
    printf 'Checking libstdc++ wrappers:\n'
    ls -l /usr/include/c++/*/cstdlib 2>/dev/null || true
    printf 'Environment variables impacting include paths:\n'
    printf '  CPATH=%s\n' "${CPATH:-<unset>}"
    printf '  C_INCLUDE_PATH=%s\n' "${C_INCLUDE_PATH:-<unset>}"
    printf '  CPLUS_INCLUDE_PATH=%s\n' "${CPLUS_INCLUDE_PATH:-<unset>}"
    printf '  LIBRARY_PATH=%s\n' "${LIBRARY_PATH:-<unset>}"
    printf '  COMPILER_PATH=%s\n' "${COMPILER_PATH:-<unset>}"
  } > "${header_log}"

  local gcc_bin="g++-12"
  if ! command -v "${gcc_bin}" >/dev/null 2>&1; then
    gcc_bin="g++"
  fi
  if command -v "${gcc_bin}" >/dev/null 2>&1; then
    {
      printf '=== %s include search order (g++ -E -v) ===\n' "${gcc_bin}"
      # EXEMPTED FROM EXTRACTION: Minimal diagnostic heredoc (single #include line), used for compiler diagnostics only
      "${gcc_bin}" -xc++ -E -v - <<'EOF'
#include <stdlib.h>
EOF
    } > "${gcc_include_log}" 2>&1 || true
  fi

  printf '%s\n' "  ${GREEN}↪ Header diagnostics written to ${header_log}${NC}"
  if [ -f "${gcc_include_log}" ]; then
    printf '%s\n' "  ${GREEN}↪ GCC include search order logged at ${gcc_include_log}${NC}"
  fi
}

# Purpose: Ensure environment variable contains a specific directory path
# Parameters: $1 = variable name, $2 = required directory path
# Returns: 0 on success
# Side effects: Modifies environment variable if directory not present
ensure_env_contains_dir() {
  local var_name="${1:-}"
  local required_dir="${2:-}"
  if [ -z "${var_name}" ] || [ -z "${required_dir}" ]; then
    return 0
  fi
  # shellcheck disable=SC1083 # Indirect expansion for dynamic variable
  local current_value="${!var_name-}"
  if [ -z "${current_value}" ]; then
    printf '%s\n' "  ${YELLOW}↪ Adding ${required_dir} to empty ${var_name}${NC}"
    export "${var_name}=${required_dir}"
  elif [[ ":${current_value}:" != *":${required_dir}:"* ]]; then
    printf '%s\n' "  ${YELLOW}↪ Prepending ${required_dir} to ${var_name}${NC}"
    export "${var_name}=${required_dir}:${current_value}"
  fi
}

# Purpose: Sanitize standard C/C++ include environment variables for OpenCV build
# Parameters: None
# Returns: 0 on success
# Side effects: Modifies CPATH, C_INCLUDE_PATH, CPLUS_INCLUDE_PATH, LIBRARY_PATH
sanitize_standard_include_env() {
  ensure_env_contains_dir "CPATH" "/usr/include"
  ensure_env_contains_dir "CPATH" "/usr/include/x86_64-linux-gnu"
  ensure_env_contains_dir "C_INCLUDE_PATH" "/usr/include"
  ensure_env_contains_dir "C_INCLUDE_PATH" "/usr/include/x86_64-linux-gnu"
  ensure_env_contains_dir "CPLUS_INCLUDE_PATH" "/usr/include"
  ensure_env_contains_dir "CPLUS_INCLUDE_PATH" "/usr/include/x86_64-linux-gnu"
  ensure_env_contains_dir "LIBRARY_PATH" "/usr/lib/x86_64-linux-gnu"
  ensure_env_contains_dir "LIBRARY_PATH" "/usr/lib"
}

# Purpose: Detect system GCC major version for toolchain package selection
# Parameters: None
# Returns: GCC major version number (e.g., "12", "13") or "13" as default
# Side effects: None
detect_system_gcc_major_version() {
  local detected_major=""
  if command -v gcc >/dev/null 2>&1; then
    # F2: Command substitution validation - validate result format
    detected_major=$(gcc -dumpversion 2>/dev/null | cut -d. -f1 | head -1 || echo "")
    # F2: Validate result is numeric
    if ! [[ "${detected_major}" =~ ^[0-9]+$ ]]; then
      detected_major=""
    fi
  fi
  if [ -z "${detected_major}" ] || ! [[ "${detected_major}" =~ ^[0-9]+$ ]]; then
    detected_major="13"
  fi
  printf '%s\n' "${detected_major}"
}

SYSTEM_GCC_MAJOR_VERSION="$(detect_system_gcc_major_version)"

