            done
            if [ "${ceres_pkg_found}" != "true" ]; then
                # A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
                printf '%s\n' "    None (expected)"
            fi
            unset ceres_pkg ceres_pkg_found ceres_pkg_list ceres_pkg_version resolved_pkg
        else
            # A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
