#===============================================================================
# BLOCK 25: JAX CUDA INSTALLATION (REINFORCEMENT LEARNING)
#===============================================================================
# Purpose: Install JAX with CUDA support via pre-built wheels for GPU-accelerated RL
# Self-contained: Yes (complete JAX CUDA installation with verification)
# Dependencies: CUDA 12.x, cuDNN 9.x, Python 3.x, pip
# Outputs: JAX with CUDA support, verified installation
#-------------------------------------------------------------------------------

# A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
printf '%s\n' "==> Installing JAX CUDA for GPU-Accelerated Reinforcement Learning"

#--- Sub-block 25.1: Auto-detect CUDA version for JAX ---
# Purpose: Dynamically detect CUDA version and map to JAX-compatible variant
# Dependencies: CUDA installation (Block 12 or earlier)
# Outputs: CUDA_FOR_JAX, CUDA_VERSION, DETECTED_CUDA
# A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
printf '%s\n' "Detecting CUDA version for JAX installation..."

# Purpose: Detect CUDA version using multiple methods and map to JAX-compatible variant
# Parameters: None (uses global CUDA_HOME if available)
# Returns: Exports CUDA_FOR_JAX, CUDA_VERSION, DETECTED_CUDA, CUDA_MAJOR, CUDA_MINOR
# Side effects: Sets global variables for JAX installation
# L4: Function documentation required for functions > 10 lines
detect_cuda_version_for_jax() {
    local cuda_full=""
    local cuda_major=""
    local cuda_minor=""
    
    # Method 1: Check nvcc
    if command -v nvcc &> /dev/null; then
        # D3e: Fix SIGPIPE error handling - add || true at pipeline end
        # D3c: Use grep -F for fixed-string matching when possible
        cuda_full=$(nvcc --version 2>/dev/null | grep -F "release" 2>/dev/null | sed 's/.*release \([0-9]\+\.[0-9]\+\).*/\1/' 2>/dev/null || printf '%s\n' "") || true
        # F2: Validate result format before use
        # A5: Bash-specific [[ ]] is acceptable here (shebang is #!/bin/bash) for regex matching
        if [ -n "${cuda_full:-}" ] && [[ "${cuda_full}" =~ ^[0-9]+\.[0-9]+$ ]]; then
            cuda_major="${cuda_full%%.*}"
            cuda_minor="${cuda_full#*.}"
            # A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
            printf '%s\n' "  Detected CUDA via nvcc: ${cuda_full}"
        fi
    fi
    
    # Method 2: Check CUDA runtime library
    if [ -z "${cuda_full:-}" ]; then
        local cuda_lib
        # D3e: Fix SIGPIPE error handling - add || true at pipeline end
        cuda_lib=$(find /usr/local/cuda-*/lib64/libcudart.so* 2>/dev/null | head -1 2>/dev/null || printf '%s\n' "")
        # F2: Validate result format before use
        if [ -n "${cuda_lib:-}" ] && [ -f "${cuda_lib}" ]; then
            # D3: Use here-string instead of echo | sed (unsafe pipe pattern)
            cuda_full=$(sed -n 's|.*cuda-\([0-9]\+\.[0-9]\+\).*|\1|p' <<< "${cuda_lib}" 2>/dev/null || printf '%s\n' "")
            # F2: Validate result format before use
            # A5: Bash-specific [[ ]] is acceptable here (shebang is #!/bin/bash) for regex matching
            if [ -n "${cuda_full:-}" ] && [[ "${cuda_full}" =~ ^[0-9]+\.[0-9]+$ ]]; then
                cuda_major="${cuda_full%%.*}"
                cuda_minor="${cuda_full#*.}"
                # A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
                printf '%s\n' "  Detected CUDA via library path: ${cuda_full}"
            # ENDIF: cuda_full format validation
            fi
        # ENDIF: cuda_lib existence check
        fi
    fi
    
    # Method 3: Check CUDA_HOME or CUDA_PATH
    if [ -z "${cuda_full:-}" ] && [ -n "${CUDA_HOME:-}" ]; then
        # D3: Use here-string instead of echo | sed (unsafe pipe pattern)
        cuda_full=$(sed -n 's|.*cuda-\([0-9]\+\.[0-9]\+\).*|\1|p' <<< "${CUDA_HOME}" 2>/dev/null || printf '%s\n' "")
        # J1: Validate file exists before reading
        if [ -z "${cuda_full:-}" ] && [ -f "${CUDA_HOME}/version.txt" ] && [ -r "${CUDA_HOME}/version.txt" ]; then
            # D3c: Use POSIX-compliant sed instead of grep -oP (Perl regex not available on all systems)
            cuda_full=$(sed -n 's/.*CUDA Version \([0-9]\+\.[0-9]\+\).*/\1/p' "${CUDA_HOME}/version.txt" 2>/dev/null || printf '%s\n' "")
        fi
        # F2: Validate result format before use
        # A5: Bash-specific [[ ]] is acceptable here (shebang is #!/bin/bash) for regex matching
        if [ -n "${cuda_full:-}" ] && [[ "${cuda_full}" =~ ^[0-9]+\.[0-9]+$ ]]; then
            cuda_major="${cuda_full%%.*}"
            cuda_minor="${cuda_full#*.}"
            # A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
            printf '%s\n' "  Detected CUDA via CUDA_HOME: ${cuda_full}"
        fi
    fi
    
    # Determine JAX-compatible CUDA version
    # JAX supports: CUDA 11.8, 12.1, 12.2, 12.3, 12.4, 12.5, 12.6
    if [ -n "${cuda_major:-}" ]; then
        if [ "${cuda_major}" = "11" ]; then
            CUDA_VERSION="11"
            CUDA_FOR_JAX="cuda11"
        elif [ "${cuda_major}" = "12" ]; then
            CUDA_VERSION="12"
            CUDA_FOR_JAX="cuda12"
        else
            CUDA_VERSION="12"
            CUDA_FOR_JAX="cuda12"
            # A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
            printf '%s\n' "  Warning: CUDA ${cuda_full:-unknown} detected, using CUDA 12 variant for JAX"
        fi
    else
        CUDA_VERSION="12"
        CUDA_FOR_JAX="cuda12"
        cuda_full="unknown"
        cuda_major="12"
        cuda_minor=""
        # A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
        printf '%s\n' "  Warning: CUDA not detected, defaulting to CUDA 12"
    fi
    
    export DETECTED_CUDA="${cuda_full:-unknown}"
    export CUDA_MAJOR="${cuda_major:-12}"
    export CUDA_MINOR="${cuda_minor:-}"
}

# Detect CUDA version
detect_cuda_version_for_jax
# A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
printf '%s\n' "  JAX CUDA variant: ${CUDA_FOR_JAX} (CUDA ${CUDA_VERSION}.x)"

