            if [ -n "${CUDNN_VERSION}" ] && [ "${CUDNN_VERSION}" != "unknown" ] && [[ "${CUDNN_VERSION}" =~ ^[0-9]+\.[0-9]+$ ]]; then
                # A5a: Use printf instead of echo (POSIX-compliant, no flag interpretation)
