# Debug: Display key configuration variables
# A5a/D3b: Use printf instead of echo for robustness
printf '%s\n' ""
printf '%s\n' "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
