printf '%s\n' "  OpenCV_DIR: ${OPENCV_DIR:-'<not set>'}"
printf '%s\n' "  Eigen3_DIR: ${EIGEN3_DIR:-'<not set>'}"
printf '%s\n' "  GLFW_CMAKE_PREFIX: ${GLFW_CMAKE_PREFIX:-'<not set>'}"
