    -DCMAKE_POSITION_INDEPENDENT_CODE=ON \
    -DOPEN3D_THIRD_PARTY_DOWNLOAD_DIR="${OPEN3D_DOWNLOAD_CACHE}" \
    -DBUILD_SHARED_LIBS=OFF \
    -DBUILD_CUDA_MODULE=ON \
    -DBUILD_GUI=ON \
