    printf '%s\n' ""
    printf '%s\n' "  Checking Open3D download cache for extracted files..."
    if [ -n "${OPEN3D_DOWNLOAD_CACHE:-}" ]; then
        find "${OPEN3D_DOWNLOAD_CACHE}" -type f -name "*webrtc*" 2>/dev/null || true
    fi
# ENDIF: WEBRTC_EXTRACTED_LIB check
