            printf '%s\n' ""
            exit 1
        fi
    fi
    
    if [ "${OPEN3D_PYTHON_REQUIRED}" != "true" ]; then
        # A5a/D3b: Use printf instead of echo for robustness
        printf '%s\n' "⚠ WARNING: Open3D Python module installation failed"
