    if ln -sf "/opt/rust/tools/bin/${binary}" "/usr/local/bin/${cmd_name}" 2>/dev/null; then
      printf '%s\n' "✓ ${binary} -> /usr/local/bin/${cmd_name}"
    else
      printf '%s\n' "✗ Failed to create symlink for ${binary}" >&2
    fi
